previewCss:
.darma-loader-darma-b10-ceiling-fan { --accent: var(--loader-color, #14b8a6); --accent-2: var(--loader-secondary-color, #5eead4); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b10-ceiling-fan::after { content: ''; position: absolute; top: 50%; left: 50%; width: 14%; height: 14%; transform: translate(-50%, -50%); border-radius: 50%; background: var(--accent); z-index: 2; }
.darma-loader-darma-b10-ceiling-fan .darma-loader-darma-b10-ceiling-fan__fan { position: relative; width: 82%; height: 82%; animation: darma-loader-darma-b10-ceiling-fan-spin calc(var(--loader-speed, 1s) * .55) linear infinite; }
.darma-loader-darma-b10-ceiling-fan .darma-loader-darma-b10-ceiling-fan__fan span { position: absolute; top: 50%; left: 50%; width: 44%; height: 17%; margin-top: -8.5%; background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 60%, var(--accent-2)), var(--accent-2)); border-radius: 30% 60% 60% 30%; transform-origin: left center; }
.darma-loader-darma-b10-ceiling-fan .darma-loader-darma-b10-ceiling-fan__fan span:nth-child(1) { transform: rotate(0deg); }
.darma-loader-darma-b10-ceiling-fan .darma-loader-darma-b10-ceiling-fan__fan span:nth-child(2) { transform: rotate(120deg); }
.darma-loader-darma-b10-ceiling-fan .darma-loader-darma-b10-ceiling-fan__fan span:nth-child(3) { transform: rotate(240deg); }
@keyframes darma-loader-darma-b10-ceiling-fan-spin { to { transform: rotate(360deg); } }

